(()=>{'use strict';let config,hash,forumTree=[],gameDefaults=null,route='run',dirty=false,toastTimer;const $=id=>document.getElementById(id),node=(t,text)=>{const e=document.createElement(t);if(text!==undefined)e.textContent=text;return e;};const pages={run:['运行管理','客户端运行','控制客户端开放状态、维护提示与停用动作。'],notices:['内容管理','公告管理','分别管理弹窗、首页公告条和右下角悬浮挂件。'],home:['内容管理','首页板块','调整四板块的显示、顺序、来源、排序和每页条数。'],game:['内容管理','游戏信息','控制详情页信息卡及字段名称、显示顺序。'],banners:['内容管理','轮播管理','管理首页精选轮播的图片、内容与跳转。'],auth:['用户管理','登录注册','使用论坛已有登录能力，保存后客户端自动同步。'],features:['用户管理','功能开关','控制客户端入口、资源操作与托盘运行。'],appearance:['系统设置','导航主题','导航菜单、主题颜色、页面文案及站点基础信息。'],version:['系统设置','版本更新','安装包地址、升级策略与更新日志。'],cache:['系统设置','数据缓存','刷新配置缓存、导出配置并查看接口地址。']};
