const fields={game:[['game_info.enabled','显示游戏信息卡片','check'],['game_info.title','卡片标题'],['game_info.empty_text','无分类信息时的提示','textarea']],run:[['run_state.mode','客户端运行状态','select:normal,maintenance,disabled'],['run_state.action','停用动作','select:notice,lock,exit'],['run_state.can_run','允许运行','check'],['run_state.message','维护公告内容','textarea'],['run_state.close_reason','停用原因'],['run_state.resume_at','预计恢复时间'],['run_state.link','公告链接']],auth:[['auth.login_enabled','允许登录','check'],['auth.register_enabled','允许注册','check'],['auth.password_login_enabled','账号密码登录','check'],['auth.sms_enabled','短信服务总开关','check'],['auth.sms_register_enabled','短信注册','check'],['auth.sms_login_enabled','短信验证码登录','check'],['auth.sms_reset_enabled','短信找回密码','check'],['auth.sms_bind_enabled','短信绑定手机','check'],['auth.qq_login_enabled','QQ 登录','check'],['auth.captcha_enabled','论坛原生验证码','check'],['auth.bind_mobile_required','要求绑定手机','check'],['auth.disabled_message','关闭提示语'],['auth.sms_login_modes','短信登录方式','modes']],features:[['features.search_enabled','帖子搜索','check'],['features.notifications_enabled','消息中心','check'],['features.posting_enabled','客户端发帖','check'],['features.reply_enabled','客户端回复','check'],['features.download_enabled','资源下载','check'],['features.sign_in_enabled','论坛签到入口','check'],['features.medals_enabled','勋章中心','check'],['features.tasks_enabled','任务中心','check'],['features.profile_save_enabled','保存个人资料','check'],['features.theme_enabled','主题设置','check'],['features.dark_mode_enabled','深浅模式切换','check'],['features.tray_enabled','后台托盘运行','check'],['collect_enabled','帖子收藏','check'],['feedback_link','报错反馈链接']],appearance:[['theme.default','默认主题色','select:blue,purple,green,orange'],['theme.available','可用主题色','colors'],['theme.allow_user_change','允许用户切换主题','check'],['theme.appearance','默认外观','select:system,light,dark'],['slogan','侧边栏标语'],['show_version','显示版本号','check'],['pagination_mode','板块加载方式','select:paged,infinite'],['games_forum_id','默认游戏板块编号','number'],['app.name','站点名称'],['app.site_url','论坛地址'],['app.api_base','客户端接口地址'],['app.image_cdn','图片服务器地址']],version:[['latest_version','最新版本号'],['minimum_version','最低版本号'],['force_update','强制升级','check'],['download_url','安装包直链'],['update_feed_url','更新源地址'],['check_interval_minutes','检查更新间隔（分钟）','number'],['changelog','更新日志（每行一条）','lines']]};
const noticeFields=[['id','公告编号'],['title','标题'],['content','内容','textarea'],['icon','图标'],['link','跳转链接'],['button_text','按钮文字'],['bg_color','背景色'],['text_color','文字色'],['enabled','显示','check'],['dismissible','允许关闭','check'],['start_at','开始时间（北京时间）'],['end_at','结束时间（北京时间）'],['auto_hide','自动隐藏秒数（零表示常驻）','number']];
const listFields={game_fields:[['key','字段标识'],['label','显示名称（可用数值占位符）'],['enabled','显示字段','check']],home_tabs:[['key','板块类型','select:latest,hot,digest,games'],['label','标签名称'],['enabled','显示','check'],['icon','图标'],['sort','帖子排序','select:lastpost,dateline,replies'],['filter','筛选条件','select:,digest,sticky'],['count','每页条数','number'],['link','查看全部链接'],['forum_ids','来源版块（可多选；空为全站）','forums']],banners:[['id','轮播编号'],['title','标题'],['slogan','标语'],['image','图片地址'],['link_type','跳转类型','select:thread,external'],['link','帖子编号或外部链接'],['button_text','按钮文字'],['enabled','显示','check']],navigation:[['id','导航编号'],['label','名称'],['page','内置页面','pages'],['url','外部链接（优先）'],['enabled','显示','check']],forum_filters:[['key','筛选类型','select:all,digest,sticky'],['label','显示名称']]};
const pageNames={home:'首页',forums:'游戏板块',search:'帖子搜索',notifications:'消息中心',profile:'用户中心',medals:'勋章中心',tasks:'任务中心',settings:'设置',thread:'帖子详情',explore:'探索分组',mine:'我的分组',all:'查看全部按钮',banner_action:'轮播按钮',search_placeholder:'搜索提示'};
const read=(obj,path)=>path.split('.').reduce((v,k)=>v?.[k],obj),write=(obj,path,v)=>{const keys=path.split('.'),last=keys.pop();let target=obj;for(const k of keys)target=target[k]||(target[k]={});target[last]=v;};
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,2000);}
async function api(action,data){const r=await fetch('admin.php?action='+action,data?{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,formhash:hash})}:{credentials:'same-origin'});const v=await r.json();if(!r.ok||v.status!=='success')throw Error(v.message||'请求失败');return v.data;}
function input(path,label,type='text',v=''){const wrap=node('label',label);let el;if(type==='check'){el=node('input');el.type='checkbox';el.checked=v!==false;wrap.className='toggle';}else if(type==='textarea'||type==='lines'){el=node('textarea');el.value=Array.isArray(v)?v.join('\n'):v||'';}else if(type.startsWith('select:')||['forums','pages','colors','modes'].includes(type)){el=node('select');let choices=type.startsWith('select:')?type.slice(7).split(',').map(k=>[k,options[k]||'未设置']):type==='pages'?Object.entries(pageNames).filter(([k])=>['home','forums','search','notifications','profile','medals','tasks','settings'].includes(k)):type==='forums'?forumTree.filter(f=>f.type!=='group').map(f=>[String(f.fid),(f.type==='sub'?'　↳ ':'')+f.name+'（'+f.fid+'）']):type==='colors'?['blue','purple','green','orange'].map(k=>[k,options[k]]):['code','password'].map(k=>[k,options[k]]);el.multiple=['forums','colors','modes'].includes(type);if(el.multiple)el.size=type==='forums'?7:3;for(const [key,text]of choices){const option=node('option',text);option.value=key;option.selected=Array.isArray(v)?v.map(String).includes(key):String(v)===key;el.append(option);}}else{el=node('input');el.type=type==='number'?'number':'text';el.value=v??'';if(type==='number'&&path==='count'){el.min=1;el.max=50;}}el.dataset.path=path;el.dataset.kind=type;wrap.append(el);return wrap;}
function val(el){return el.type==='checkbox'?el.checked:el.multiple?[...el.selectedOptions].map(o=>el.dataset.kind==='forums'?Number(o.value):o.value):el.dataset.kind==='number'?Number(el.value):el.dataset.kind==='lines'?el.value.split('\n').map(v=>v.trim()).filter(Boolean):el.value;}
function card(title){const box=node('section');box.className='card';if(title)box.append(node('h2',title));return box;}
function records(group,title){const box=card(title),list=node('div');list.dataset.container=group;const items=group==='navigation'?config.navigation.items:group==='game_fields'?config.game_info.fields:config[group]||[];function add(item){const row=node('details');row.open=list.children.length===0;row.className='record';row.dataset.oldId=item.id||item.key||'';const head=node('summary');head.className='record-head';head.append(node('b',item.label||item.title||title));const tools=node('div');tools.className='record-tools';for(const [text,dir]of [['上移',-1],['下移',1]]){const b=node('button',text);b.className='secondary';b.onclick=()=>{const sibling=dir<0?row.previousElementSibling:row.nextElementSibling;if(sibling){dir<0?list.insertBefore(row,sibling):list.insertBefore(sibling,row);dirty=true;}};tools.append(b);}const remove=node('button','删除');remove.className='danger';remove.onclick=()=>{row.remove();dirty=true;};tools.append(remove);head.append(tools);row.append(head);const grid=node('div');grid.className='grid';for(const f of listFields[group]||noticeFields)grid.append(input(f[0],f[1],f[2]||'text',read(item,f[0])??''));row.append(grid);list.append(row);}for(const item of items)add(item);box.append(list);if(group==='game_fields'){const restore=node('button','恢复缺失的默认字段');restore.className='secondary';restore.onclick=()=>{const keys=new Set([...list.querySelectorAll('[data-path=key]')].map(n=>n.value));for(const field of gameDefaults?.fields||[])if(!keys.has(field.key))add(field);dirty=true;};box.append(restore);}if(group!=='home_tabs'){const b=node('button','新增'+title);b.className='secondary';b.onclick=()=>{add({id:'item-'+Date.now(),key:group==='game_fields'?'field_'+Date.now():'all',label:'新项目',enabled:true,dismissible:true,auto_hide:0,page:'home',link_type:'thread',link:'1',button_text:'查看'});dirty=true;};box.append(b);}return box;}
function render(){const content=$('content');content.replaceChildren();const [,title,desc]=pages[route];content.append(node('h1',title),Object.assign(node('p',desc),{className:'muted'}));document.querySelectorAll('aside a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));if(fields[route]){const box=card('配置设置'),grid=node('div');grid.className='grid';for(const f of fields[route])grid.append(input(f[0],f[1],f[2]||'text',read(config,f[0])));box.append(grid);content.append(box);}if(route==='notices')for(const [g,t]of [['announcements','弹窗公告'],['home_notices','首页公告条'],['floating_notices','右下角悬浮挂件']])content.append(records(g,t));if(route==='game')content.append(records('game_fields','字段列表'));if(route==='home')content.append(records('home_tabs','首页板块'));if(route==='banners')content.append(records('banners','精选轮播'));if(route==='appearance'){content.append(records('navigation','导航菜单'),records('forum_filters','板块筛选'));const box=card('页面显示文案'),grid=node('div');grid.className='grid';for(const [key,value]of Object.entries(config.layout_labels||{}))grid.append(input('layout_labels.'+key,pageNames[key]||'其他页面文案','text',value));box.append(grid);content.append(box);}if(route==='auth'){const box=card('其他登录方式');for(const text of ['微信登录','邮箱登录','邮箱验证']){const row=node('div');row.className='disabled-row';row.append(node('span',text),node('span','尚未接入'));box.append(row);}content.append(box);}if(route==='cache'){const box=card('配置数据');box.append(node('p','缓存刷新不修改配置。配置导出仅包含客户端公开设置，请妥善保管。'));const refresh=node('button','刷新缓存');refresh.onclick=refreshCache;const exp=node('button','导出配置');exp.className='secondary';exp.onclick=()=>{const c=structuredClone(config);delete c._revision;delete c._updated_at;const url=URL.createObjectURL(new Blob([JSON.stringify(c,null,2)],{type:'application/json'}));const a=node('a');a.href=url;a.download='客户端公开配置.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};box.append(refresh,exp);for(const [title,url]of [['公开配置接口',new URL('client_config.php',location.href).href],['帖子详情接口',new URL('thread.php',location.href).href],['更新源',config.update_feed_url]]){box.append(node('h3',title),node('code',url));}content.append(box);}else{const bar=node('div');bar.className='save-bar';bar.append(node('span','保存后客户端自动同步'));const save=node('button','保存当前页面');save.id='savePage';save.onclick=savePage;bar.append(save);content.append(bar);}content.oninput=()=>{dirty=true;$('status').textContent='当前页面有未保存的修改';};content.onchange=content.oninput;dirty=false;}
function closeNav(){document.body.classList.remove('nav-open');$('nav').inert=window.innerWidth<768;$('navToggle').setAttribute('aria-expanded','false');}
function buildNavigation(){const groups=$('navGroups');groups.replaceChildren();let prev='',details,links;for(const [key,[group,title]]of Object.entries(pages)){if(group!==prev){details=node('details');details.className='nav-group';details.open=window.innerWidth>=768;const summary=node('summary',group);details.append(summary);links=node('div');details.append(links);groups.append(details);details.addEventListener('toggle',event=>{const current=event.currentTarget;if(window.innerWidth<768&&current.open)for(const other of groups.children)if(other!==current)other.open=false;});prev=group;}const a=node('a',title);a.href='#'+key;a.onclick=e=>{e.preventDefault();navigate(key);};links.append(a);}}
function navigate(key){if(dirty&&!confirm('当前页面有未保存的修改，是否放弃并切换？'))return;closeNav();route=key;history.replaceState(null,'','#'+key);render();window.scrollTo(0,0);}
async function refreshCache(){try{await api('refresh_cache',{});toast('缓存已刷新');}catch(e){toast(e.message);}}
async function savePage(){const button=$('savePage');button.disabled=true;$('status').textContent='正在保存…';try{const next=structuredClone(config);for(const el of $('content').querySelectorAll('[data-path]'))if(!el.closest('.record'))write(next,el.dataset.path,val(el));for(const box of $('content').querySelectorAll('[data-container]')){const group=box.dataset.container,items=[...box.children].map(row=>{const old=(group==='navigation'?config.navigation.items:group==='game_fields'?config.game_info.fields:config[group]||[]).find(i=>(i.id||i.key||'')===row.dataset.oldId)||{};const item={...old};for(const el of row.querySelectorAll('[data-path]'))write(item,el.dataset.path,val(el));if(['announcements','home_notices','floating_notices'].includes(group))item.updated_at=Math.max(Math.floor(Date.now()/1000),(old.updated_at||0)+1);return item;});if(group==='game_fields'){next.game_info.fields=items;}else if(group==='navigation'){next.navigation.items=items;next.navigation.order=items.map(i=>i.id);}else next[group]=items;}if(route==='version')next.update={...next.update,force_min_version:next.minimum_version,check_interval:next.check_interval_minutes*60,changelog:next.changelog};const result=await api('save',{config:next,expected_revision:config._revision});config=result.config;hash=result.formhash;render();$('status').textContent='已保存';toast('保存成功，客户端正在同步');}catch(e){toast('保存失败：'+e.message);$('status').textContent='保存失败';}finally{button.disabled=false;}}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(pages[next]){if(dirty&&!confirm('放弃当前页面未保存的修改？')){history.replaceState(null,'','#'+route);return;}route=next;render();}});$('refreshCache').onclick=refreshCache;$('navToggle').onclick=()=>{const open=!document.body.classList.contains('nav-open');document.body.classList.toggle('nav-open',open);$('navToggle').setAttribute('aria-expanded',String(open));$('nav').inert=!open;if(open){const active=$('nav').querySelector('a.active');if(active)active.closest('details').open=true;$('navClose').focus();}};$('navClose').onclick=()=>{closeNav();$('navToggle').focus();};$('navMask').onclick=closeNav;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNav();});window.matchMedia('(min-width:768px)').addEventListener('change',e=>{closeNav();for(const group of $('navGroups').children)group.open=e.matches;});buildNavigation();closeNav();api('get_overview').then(v=>{config=v.config;hash=v.formhash;forumTree=v.forum_tree||[];gameDefaults=v.game_info_defaults||structuredClone(config.game_info);route=pages[location.hash.slice(1)]?location.hash.slice(1):'run';render();$('status').textContent='配置已加载';}).catch(e=>{$('status').textContent='加载失败：'+e.message;toast(e.message);});})();
</script></body></html>
